from __future__ import annotations

from dataclasses import dataclass

from app.services import session_store as store


@dataclass
class Session:
    token: str
    user_id: str
    expires_at: int


def current_session(token: str) -> Session | None:
    return store.find(token)


def expire_all(user_id: str) -> int:
    return store.delete_where(user_id=user_id)
